#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int maxFrequencyElements(std::vector<int>& nums) {
        std::unordered_map<int, int> counts;
        int maxF = 0;
        for (int x : nums) {
            maxF = std::max(maxF, ++counts[x]);
        }
        int ans = 0;
        for (const auto& [k, v] : counts) {
            if (v == maxF) ans += v;
        }
        return ans;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int maxFrequencyElements(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        int maxF = 0;
        for (int x : nums) {
            int f = counts.getOrDefault(x, 0) + 1;
            counts.put(x, f);
            if (f > maxF) maxF = f;
        }
        int ans = 0;
        for (int f : counts.values()) {
            if (f == maxF) ans += f;
        }
        return ans;
    }
}

var maxFrequencyElements = function(nums) {
    const counts = new Map();
    let maxF = 0;
    for (const x of nums) {
        const f = (counts.get(x) || 0) + 1;
        counts.set(x, f);
        if (f > maxF) maxF = f;
    }
    let ans = 0;
    for (const f of counts.values()) {
        if (f === maxF) ans += f;
    }
    return ans;
};
